data.minimal_example:
final AdDisplayContainer _adDisplayContainer = AdDisplayContainer(
  onContainerAdded: (AdDisplayContainer container) {
    final AdsLoader adsLoader = AdsLoader(
      container: container,
      onAdsLoaded: (OnAdsLoadedData data) {
        data.manager.init(settings: AdsRenderingSettings(enablePreloading: true));
        data.manager.start();
      },
      onAdsLoadError: (AdsLoadErrorData data) {},
    );
    adsLoader.requestAds(AdsRequest(adTagUrl: 'YOUR_AD_TAG_URL'));
  },
);
